import { CORE_ABI_VERSION as ABI_VERSION, type CoreManifest } from '@mpf/core'

/** `computeTotal` stays `computeTotal`; `2fa-setup` -> `_2faSetup`. */
export function tsIdent(name: string): string {
  const camel = name
    .replace(/[^A-Za-z0-9]+([A-Za-z0-9])/g, (_, c: string) => c.toUpperCase())
    .replace(/[^A-Za-z0-9_$]/g, '')
  return /^[0-9]/.test(camel) ? `_${camel}` : camel || 'fn'
}

/**
 * Dependency-free TypeScript host for the web target: the same ABI walk as the factory's
 * Node host, plus one typed wrapper per manifest function. Generated; do not edit.
 */
export function tsBinding(manifest: CoreManifest, wasmImport = './mpf_core.wasm?url'): string {
  const fns = manifest.functions.map((f) => ({ ...f, ident: tsIdent(f.name) }))
  return `// Generated by multiplat-factory from the shared core manifest. Do not edit.
// ABI: docs/ABI.md in the factory (version ${ABI_VERSION}).
import wasmUrl from '${wasmImport}'

export interface CoreError { code: string; message: string }
export class CoreCallError extends Error {
  constructor(public readonly code: string, message: string) { super(\`\${code}: \${message}\`) }
}

type Envelope = { ok: true; value: unknown } | { ok: false; error: CoreError }

interface Exports {
  memory: WebAssembly.Memory
  mpf_abi_version(): number
  mpf_alloc(len: number): number
  mpf_free(ptr: number, len: number): void
  mpf_call(namePtr: number, nameLen: number, reqPtr: number, reqLen: number): bigint
  mpf_manifest(): bigint
}

export interface Core {
  /** Call any core function by manifest name; throws CoreCallError on an error envelope. */
  call(name: string, input: unknown): unknown
  manifest(): unknown
}

function wrap(instance: WebAssembly.Instance): Core {
  const ex = instance.exports as unknown as Exports
  const version = ex.mpf_abi_version()
  if (version !== ${ABI_VERSION}) throw new Error(\`core ABI version \${version}; this host speaks ${ABI_VERSION}\`)
  const enc = new TextEncoder()
  const dec = new TextDecoder()
  const write = (s: string): { ptr: number; len: number } => {
    const b = enc.encode(s)
    const ptr = ex.mpf_alloc(b.length)
    new Uint8Array(ex.memory.buffer, ptr, b.length).set(b)
    return { ptr, len: b.length }
  }
  const take = (packed: bigint): string => {
    const ptr = Number(packed >> 32n)
    const len = Number(packed & 0xffff_ffffn)
    const s = dec.decode(new Uint8Array(ex.memory.buffer, ptr, len))
    ex.mpf_free(ptr, len)
    return s
  }
  return {
    call(name, input) {
      const n = write(name)
      const r = write(JSON.stringify(input ?? null))
      let env: Envelope
      try {
        env = JSON.parse(take(ex.mpf_call(n.ptr, n.len, r.ptr, r.len))) as Envelope
      } finally {
        ex.mpf_free(n.ptr, n.len)
        ex.mpf_free(r.ptr, r.len)
      }
      if (!env.ok) throw new CoreCallError(env.error.code, env.error.message)
      return env.value
    },
    manifest() {
      return JSON.parse(take(ex.mpf_manifest()))
    },
  }
}

/** Instantiate from module bytes (tests, workers, or a custom loader). */
export async function loadCoreFrom(bytes: BufferSource): Promise<Core> {
  const { instance } = await WebAssembly.instantiate(bytes, {})
  return wrap(instance)
}

let corePromise: Promise<Core> | undefined

/** Load the bundled module once (fetched by URL in the browser); safe to call repeatedly. */
export function loadCore(): Promise<Core> {
  corePromise ??= (async () => {
    const response = await fetch(wasmUrl)
    if (!response.ok) throw new Error(\`cannot load \${wasmUrl}: \${response.status}\`)
    return loadCoreFrom(await response.arrayBuffer())
  })()
  return corePromise
}

/** Call any core function by manifest name. */
export async function callCore(name: string, input: unknown): Promise<unknown> {
  return (await loadCore()).call(name, input)
}

${fns
  .map(
    (f) => `/** ${f.description.replace(/\*\//g, '* /') || f.name} */
export function ${f.ident}(input: ${f.ident}Input): Promise<${f.ident}Output> {
  return callCore(${JSON.stringify(f.name)}, input) as Promise<${f.ident}Output>
}
/** Input schema: ${JSON.stringify(f.inputSchema)} */
export type ${f.ident}Input = ${tsTypeFor(f.inputSchema)}
/** Output schema: ${JSON.stringify(f.outputSchema)} */
export type ${f.ident}Output = ${tsTypeFor(f.outputSchema)}
`,
  )
  .join('\n')}`
}

/** Vitest parity suite: every vector file through the module read from disk. */
export function tsParityTest(): string {
  return `// Generated by multiplat-factory. Do not edit: vectors live in ./vectors/.
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { beforeAll, describe, expect, it } from 'vitest'
import wasmUrl from './mpf_core.wasm?url'
import { CoreCallError, loadCoreFrom, type Core } from './mpf-core'

interface VectorSet { function: string; vectors: { id: string; input: unknown; expected: unknown }[] }
const sets = Object.values(import.meta.glob('./vectors/*.json', { eager: true, import: 'default' })) as VectorSet[]

function canonical(v: unknown): string {
  if (Array.isArray(v)) return \`[\${v.map(canonical).join(',')}]\`
  if (v && typeof v === 'object') return \`{\${Object.keys(v).sort().map((k) => \`\${JSON.stringify(k)}:\${canonical((v as Record<string, unknown>)[k])}\`).join(',')}}\`
  return JSON.stringify(v)
}

let core: Core
beforeAll(async () => {
  const path = wasmUrl.startsWith('file:') ? fileURLToPath(wasmUrl) : join(process.cwd(), wasmUrl)
  core = await loadCoreFrom(await readFile(path))
})

describe('shared core parity', () => {
  it('has vector files', () => {
    expect(sets.length).toBeGreaterThan(0)
  })
  for (const set of sets) {
    describe(set.function, () => {
      for (const v of set.vectors) {
        it(v.id, () => {
          try {
            expect(canonical(core.call(set.function, v.input))).toBe(canonical(v.expected))
          } catch (err) {
            if (err instanceof CoreCallError) throw new Error(\`core error \${err.message}\`)
            throw err
          }
        })
      }
    })
  }
})
`
}

/** A best-effort TypeScript type from a JSON Schema; falls back to unknown where the schema is loose. */
export function tsTypeFor(schema: Record<string, unknown>, depth = 0): string {
  if (depth > 6) return 'unknown'
  const type = schema.type
  const enumValues = schema.enum as unknown[] | undefined
  if (enumValues?.length) return enumValues.map((v) => JSON.stringify(v)).join(' | ')
  if (Array.isArray(schema.anyOf))
    return (
      (schema.anyOf as Record<string, unknown>[]).map((s) => tsTypeFor(s, depth + 1)).join(' | ') ||
      'unknown'
    )
  if (Array.isArray(schema.oneOf))
    return (
      (schema.oneOf as Record<string, unknown>[]).map((s) => tsTypeFor(s, depth + 1)).join(' | ') ||
      'unknown'
    )
  if (Array.isArray(type))
    return type.map((t) => tsTypeFor({ ...schema, type: t }, depth + 1)).join(' | ')
  switch (type) {
    case 'string':
      return 'string'
    case 'number':
    case 'integer':
      return 'number'
    case 'boolean':
      return 'boolean'
    case 'null':
      return 'null'
    case 'array': {
      const items = schema.items as Record<string, unknown> | undefined
      return `${items ? parenthesize(tsTypeFor(items, depth + 1)) : 'unknown'}[]`
    }
    case 'object': {
      const props = (schema.properties ?? {}) as Record<string, Record<string, unknown>>
      const required = new Set((schema.required as string[] | undefined) ?? [])
      const entries = Object.entries(props).map(
        ([k, v]) => `${JSON.stringify(k)}${required.has(k) ? '' : '?'}: ${tsTypeFor(v, depth + 1)}`,
      )
      const extra = schema.additionalProperties
      if (!entries.length)
        return extra === false ? 'Record<string, never>' : 'Record<string, unknown>'
      return `{ ${entries.join('; ')}${extra && typeof extra === 'object' ? `; [key: string]: ${tsTypeFor(extra as Record<string, unknown>, depth + 1)}` : ''} }`
    }
    default:
      return 'unknown'
  }
}

function parenthesize(t: string): string {
  return /[|&]/.test(t) ? `(${t})` : t
}
